(function(){"use strict";var SAVED=["f30:","f30-frame:","dev-panel","slacky-shell:","slackbot-conversation:","slackbot-design","rs:"];function wipe(store){try{Object.keys(store).forEach(function(k){if(SAVED.some(function(p){return k.indexOf(p)===0}))store.removeItem(k)})}catch(e){}}try{if(window.sessionStorage.getItem("rs:reset")==="1"){wipe(window.sessionStorage);wipe(window.localStorage)}}catch(e){}function reset(){wipe(window.sessionStorage);wipe(window.localStorage);try{window.sessionStorage.setItem("rs:reset","1")}catch(e){}window.location.replace(window.location.pathname)}var clicks=[];function addResetSpot(){if(document.getElementById("rs-reset"))return;var spot=document.createElement("div");spot.id="rs-reset";spot.setAttribute("aria-hidden","true");spot.addEventListener("click",function(e){e.preventDefault();e.stopPropagation();var now=Date.now();clicks=clicks.filter(function(t){return now-t<1200}).concat(now);if(clicks.length>=3)reset()},true);document.body.appendChild(spot)}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",addResetSpot);else addResetSpot();function typing(t){var tag=t&&t.tagName;return!!t&&(t.isContentEditable||tag==="INPUT"||tag==="TEXTAREA"||tag==="SELECT")}window.addEventListener("keydown",function(e){if(e.metaKey||e.ctrlKey||e.altKey)return;if(e.key==="Tab"){e.stopImmediatePropagation();return}if(typing(e.target))return;if(/^[dpv]$/i.test(e.key)||e.shiftKey&&/^Arrow/.test(e.key)){e.stopImmediatePropagation();e.preventDefault()}},true);var KIT=window.F30_KIT||"../../../../";function activityPage(){return'<div class="rs-activity"><div class="p-activity_head"><div class="p-activity_head__top"><h1 class="p-activity_head__title">Activity</h1><button type="button" class="p-unreads_toggle p-nux_unreads_toggle" aria-pressed="false" aria-label="Filter by unread messages"><span class="p-unreads_toggle__label">Unreads</span><span class="p-unreads_toggle__switch" aria-hidden="true"><span class="p-unreads_toggle__switch__handle"></span></span></button></div><div class="p-channel_tabs"><button type="button" class="p-channel_tabs__tab p-channel_tabs__tab--active">All</button></div></div><div class="rs-activity__list"><div class="p-nux_empty p-nux_empty--fill"><span class="p-nux_empty__emoji" aria-hidden="true">\u2705</span><p class="p-nux_empty__title">You\u2019re all caught up</p><p class="p-nux_empty__desc">Looks like things are quiet for now. When there\u2019s new activity, you\u2019ll see it here.</p></div></div><div class="p-nux_pane rs-activity__pane"><img src="'+KIT+'shared/assets/images/webapp-nux/empty-activity-light.svg" alt="@ symbol illustration"></div></div>'}function open(S,page){S.returnToHomeRail();S.clearSidebarSelection();S.showPage(page);S.renderAgenticSidebar()}function hook(S){S.PAGES["rs-activity"]=activityPage;document.addEventListener("click",function(e){var t=e.target;if(!t||!t.closest)return;if(t.closest('[data-ag-nav="activity"]')){e.preventDefault();e.stopImmediatePropagation();open(S,"rs-activity");return}var h=t.closest(".p-channel_sidebar__section_heading");var label=h&&!h.hasAttribute("data-ag-section")&&h.querySelector(".p-channel_sidebar__section_heading_label");if(label&&label.textContent.trim()==="Agents"&&S.PAGES.agents){e.preventDefault();e.stopImmediatePropagation();open(S,"agents")}},true)}(function wait(n){if(window.SHELL&&window.SHELL.PAGES){hook(window.SHELL);return}if(n<400)window.setTimeout(function(){wait(n+1)},25)})(0)})();
